import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("No suitable girl found")
        return

    idx = 0
    N = int(data[idx])
    M = int(data[idx + 1])
    idx += 2

    if N == 0 or M == 0:
        print("No suitable girl found")
        return

    matrix = []
    for i in range(N):
        row = list(map(int, data[idx:idx + M]))
        idx += M
        matrix.append(row)

    # Find Rohit's house (1 at (1,1) in 1-indexed)
    rohit_r, rohit_c = -1, -1
    girls = []
    for r in range(N):
        for c in range(M):
            if matrix[r][c] == 1:
                if r == 0 and c == 0:
                    rohit_r, rohit_c = r, c
                else:
                    girls.append((r, c))

    if rohit_r == -1 or rohit_c == -1:
        print("No suitable girl found")
        return

    # Check if any girl exists
    if not girls:
        print("No suitable girl found")
        return

    # Compute qualities for each girl
    girl_qualities = {}
    for (gr, gc) in girls:
        count = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = gr + dr, gc + dc
                if 0 <= nr < N and 0 <= nc < M:
                    if matrix[nr][nc] == 1:
                        count += 1
        girl_qualities[(gr, gc)] = count

    # BFS to compute distances from Rohit's house
    dist = [[-1] * M for _ in range(N)]
    q = deque()
    dist[rohit_r][rohit_c] = 0
    q.append((rohit_r, rohit_c))

    while q:
        r, c = q.popleft()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < M and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))

    # Find best girl: max qualities, then min distance, then check for ties
    best_quality = -1
    best_distance = float('inf')
    best_girls = []

    for (gr, gc), quality in girl_qualities.items():
        d = dist[gr][gc]
        if quality > 0:  # Only consider girls with at least one quality
            if quality > best_quality:
                best_quality = quality
                best_distance = d
                best_girls = [(gr, gc)]
            elif quality == best_quality:
                if d < best_distance:
                    best_distance = d
                    best_girls = [(gr, gc)]
                elif d == best_distance:
                    best_girls.append((gr, gc))

    if best_quality == -1 or best_quality == 0:
        print("No suitable girl found")
        return

    if len(best_girls) >= 2:
        print("He's not interested in polygamy")
    else:
        gr, gc = best_girls[0]
        print(f"{gr + 1}:{gc + 1}:{best_quality}")

if __name__ == "__main__":
    main()
